def transform(grid):
    h, w = len(grid), len(grid[0])
    removed = {v for v in grid[0] if v != 0}
    objects = []
    used = set()

    def find_at(r, c):
        for obj in objects:
            if (r, c) in obj[1]:
                return obj
        return None

    for r in range(2, h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or color in removed or (r, c) in used:
                continue
            if c + 1 < w and grid[r][c + 1] == color:
                cells = []
                cc = c
                while cc < w and grid[r][cc] == color:
                    cells.append((r, cc))
                    cc += 1
                side = find_at(r - 1, c) or find_at(r + 1, c)
                if side:
                    cells += side[1]
                    objects.remove(side)
                objects.append((color, cells))
                used.update(cells)
            elif r + 1 < h and grid[r + 1][c] == color:
                cells = []
                rr = r
                while rr < h and grid[rr][c] == color:
                    cells.append((rr, c))
                    rr += 1
                objects.append((color, cells))
                used.update(cells)

    out = [[0] * w for _ in range(h)]
    out[0] = grid[0][:]
    objects.sort(key=lambda obj: min(r for r, c in obj[1]), reverse=True)

    for color, cells in objects:
        while True:
            moved = [(r + 1, c) for r, c in cells]
            if any(r >= h or out[r][c] != 0 for r, c in moved):
                break
            cells = moved
        for r, c in cells:
            out[r][c] = color

    return out
